const input = $input.first().json;

const body =
  input.body && typeof input.body === 'object'
    ? input.body
    : input;

if (
  typeof body.question !== 'string' ||
  !body.question.trim()
) {
  throw new Error(
    'UI Judge input error: question must be a non-empty string.'
  );
}

if (
  !Array.isArray(body.answers) ||
  body.answers.length < 1 ||
  body.answers.length > 10
) {
  throw new Error(
    'UI Judge input error: answers must contain 1 to 10 entries.'
  );
}

const answers = body.answers.map((answer, index) => {
  if (
    !Number.isInteger(answer.agentId) ||
    answer.agentId < 1 ||
    answer.agentId > 10 ||
    typeof answer.role !== 'string' ||
    !answer.role.trim() ||
    typeof answer.task !== 'string' ||
    !answer.task.trim() ||
    typeof answer.answer !== 'string' ||
    !answer.answer.trim()
  ) {
    throw new Error(
      'UI Judge input error: invalid answer at index ' + index + '.'
    );
  }

  return {
    ...answer,
    role: answer.role.trim(),
    task: answer.task.trim(),
    answer: answer.answer.trim(),
  };
});

return [
  {
    json: {
      question: body.question.trim(),
      replyLanguage: ['en', 'fr', 'tr'].includes(body.replyLanguage) ? body.replyLanguage : undefined,
      openaiModel:
        typeof body.openaiModel === 'string' && body.openaiModel.trim()
          ? body.openaiModel.trim()
          : 'gpt-5-mini',
      questionType:
        typeof body.questionType === 'string' && body.questionType.trim()
          ? body.questionType.trim()
          : 'genel',
      complexity:
        typeof body.complexity === 'string' && body.complexity.trim()
          ? body.complexity.trim()
          : 'low',
      diagramRequirement: body.diagramRequirement,
      diagramPreference: body.diagramPreference,
      reviewDraft: body.reviewDraft,
      agentCount: answers.length,
      answers,
    },
  },
];
